TLM.f("Tempora/Quad5-5Feria",{"officium":"Feria Sexta infra Hebdomadam Passionis","rule":["no Gloria","Suffragium=Ecclesiæ,Papa;;","Prefatio=Quad5","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"fallback":"Tempora/Quad5-0","sections":{"Introitus":[{"k":"ref","la":"Ps 30:10, 16, 18"},{"k":"text","la":"Miserére mihi, Dómine, quóniam tríbulor: líbera me, et éripe me de mánibus inimicórum meórum et a persequéntibus me: Dómine, non confúndar, quóniam invocávi te."},{"k":"ref","la":"Ps 30:2"},{"k":"text","la":"In te, Dómine, sperávi, non confúndar in ætérnum: in justítia tua libera me."},{"k":"text","la":"Miserére mihi, Dómine, quóniam tríbulor: líbera me, et éripe me de mánibus inimicórum meórum et a persequéntibus me: Dómine, non confúndar, quóniam invocávi te."}],"Oratio":[{"k":"text","la":"Córdibus nostris, quǽsumus, Dómine, grátiam tuam benígnus infúnde: ut peccáta nostra castigatióne voluntária cohibéntes, temporáliter pótius macerémur, quam supplíciis deputémur ætérnis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Jeremíæ Prophétæ"},{"k":"ref","la":"Jer 17:13-18"},{"k":"text","la":"In diébus illis: Dixit Jeremías: Dómine, omnes, qui te derelínquunt, confundéntur: recedéntes a te in terra scribéntur: quóniam dereliquérunt venam aquárum vivéntium Dóminum. Sana me. Dómine, et sanábor: salvum me fac, et salvus ero: quóniam laus mea tu es. Ecce, ipsi dicunt ad me: Ubi est verbum Dómini? Véniat. Et ego non sum turbátus, te pastórem sequens: et diem hóminis non desiderávi, tu scis. Quod egréssum est de lábiis meis, rectum in conspéctu tuo fuit. Non sis tu mihi formídini, spes mea tu in die afflictiónis. Confundántur, qui me persequúntur, et non confúndar ego: páveant illi, et non páveam ego. Induc super eos diem afflictiónis, et dúplici contritióne cóntere eos, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 34:20, 22"},{"k":"text","la":"Pacífice loquebántur mihi inimíci mei: et in ira molésti erant mihi."},{"k":"text","la":"Vidísti, Dómine, ne síleas: ne discédas a me.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis."},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)","mark":"V"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 11:47-54"},{"k":"text","la":"In illo témpore: Collegérunt pontífices et pharisǽi concílium advérsus Jesum, et dicébant: Quid fácimus, quia hic homo multa signa facit? Si dimíttimus eum sic, omnes credent in eum: et vénient Románi, et tollent nostrum locum et gentem. Unus autem ex ipsis, Cáiphas nómine, cum esset póntifex anni illíus, dixit eis: Vos nescítis quidquam, nec cogitátis, quia éxpedit vobis, ut unus moriátur homo pro pópulo, et non tota gens péreat. Hoc autem a semetípso non dixit: sed cum esset póntifex anni illíus, prophetávit, quod Jesus moritúrus erat pro gente, et non tantum pro gente, sed ut fílios Dei, qui erant dispérsi, congregáret in unum. Ab illo ergo die cogitavérunt, ut interfícerent eum. Jesus ergo jam non in palam ambulábat apud Judǽos: sed ábiit in regiónem juxta desértum, in civitátem, quæ dícitur Ephrem, et ibi morabátur cum discípulis suis."}],"Offertorium":[{"k":"ref","la":"Ps 118:12, 121, 42"},{"k":"text","la":"Benedíctus es, Dómine, doce me justificatiónes tuas: et non tradas calumniántibus me supérbis: et respondébo exprobrántibus mihi verbum."}],"Secreta":[{"k":"text","la":"Præsta nobis, miséricors Deus: ut digne tuis servíre semper altáribus mereámur; et eórum perpétua participatióne salvári."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 26:12"},{"k":"text","la":"Ne tradíderis me, Dómine, in animas persequéntium me: quóniam insurrexérunt in me testes iníqui, et mentíta est iníquitas sibi."}],"Postcommunio":[{"k":"text","la":"Sumpti sacrifícii, Dómine, perpetua nos tuítio non derelínquat: et nóxia semper a nobis cuncta depéllat."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut, qui protectiónis tuæ grátiam quǽrimus, liberáti a malis ómnibus, secúra tibi mente serviámus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Commemoratio Septem Dolorum B. M. V."},{"k":"text","la":"Deus, in cujus passióne, secúndum Simeónis prophetíam, dulcíssimam ánimam gloriósæ Vírginis et Matris Maríæ dolóris gladius pertransívit: concéde propítius; ut, qui transfixiónem ejus et passiónem venerándo recólimus, gloriósis méritis et précibus ómnium Sanctórum Cruci fidéliter astántium intercedéntibus, passiónis tuæ efféctum felícem consequámur:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Secreta":[{"k":"rubric","la":"Commemoratio Septem Dolorum B. M. V."},{"k":"text","la":"Offérimus tibi preces et hóstias, Dómine Jesu Christe, humíliter supplicántes: ut, qui Transfixiónem dulcíssimi spíritus beátæ Maríæ, Matris tuæ, précibus recensémus; suo suorúmque sub Cruce Sanctórum consórtium multiplicáto piíssimo intervéntu, méritis mortis tuæ, méritum cum beátis habeámus:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Commemoratio Septem Dolorum B. M. V."},{"k":"text","la":"Sacrifícia, quæ súmpsimus, Dómine Jesu Christe, Transfixiónem Matris tuæ et Vírginis devóte celebrántes: nobis ímpetrent apud cleméntiam tuam omnis boni salutáris efféctum:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"69fc317ba92c1487":{"t":"Ps 30, 10 i 16 i 18; Ps 30, 2\n(Ps 30, 10 i 16 i 18) Smiluj mi se, Gospodine, jer sam u tjeskobi. Izbavi me od onih koji me mrze i progone. Gospodine, ne daj da se smetem, jer tebe zazivljem. (Ps 30, 2) U tebe se, Gospodine, uzdam, ne daj da se razočaram ikada. U svojoj pravednosti izbavi me i spasi me. (Ps 30, 10 i 16 i 18) Smiluj mi se, Gospodine, jer sam u tjeskobi. Izbavi me od onih koji me mrze i progone. Gospodine, ne daj da se smetem, jer tebe zazivljem. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]","kn":"(Ps, 30, 10, 18, 18). Smiluj mi se, Gospodine, jer sam u tjeskobi, izbavi me i spasi me iz ruku neprijatelja mojih 1 onih, koji me progone. Gospodine, ne ću se zastidjeti, jer se u Tebe uzdam! (Ps. 30, 2). U Tebe se, Gospodine, uzdam, o, da se ne postidim dovijeka!","knRef":"Kniewald 1942, str. 208–209 (snimka 105) (OCR)"},"caddee84d322f9a1":{"t":"<i>Pomolimo se</i>.\nDobrostivo ulij u naša srca, molimo, Gospodine, svoju milost da suzbijajući svojevoljnim mrtvenjem svoje grijehe radije trpimo sada u vremenu nego da budemo osuđeni na vječne muke.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, ulij u srca naša milost svoju, da radije sprečavamo grijehe svojevoljnom trapnjom vremenito trpeći, nego da budemo predani u vječne muke. Po G. n.","knRef":"Kniewald 1942, str. 208–209 (snimka 105) (OCR)"},"143760c48509686e":{"t":"Jr 17, 13-18\nČitanje Jeremije proroka. U one dane reče Jeremija: Gospodine, svi koji te ostavljaju smest će se, koji se udaljuju od tebe zapisat će se u prah, jer su napustili Gospodina, vrelo žive vode. Izliječi me, Gospodine, da budem zdrav, pomozi mi i spasit ću se, jer si ti moja hvala. Evo, oni mi govore: Gdje je Gospodnja riječ? Neka dođe! A ja se nisam smeo idući za tobom pastirom. Ti znaš da nisam težio za životom ljudskim. Vidio si da su moje riječi bile pravedne. Ne daj da se strašim pred tobom, koji si moje utočište u dan nevolje! Neka se smetu moji neprijatelji, a ja ne, neka se plaše oni, a ja da se ne bojim. Neka dožive dan nevolje i slomi ih dvostrukim udarcem, Gospodine, Bože naš!","kn":"Čitanje Jeremlje Proroka (17, 13-18). U one dane reče Jeremija: Gospodine, svi. koji te ostavljaju, smesti će se: koji odstupaju od tebe, bit će zapisani u prahu; jer ostaviše vrelo vode žive. Gospodina. Izliječi me, Gospodine, i ozdravit ću; spasi me, i bit ću spašen; jer ti si hvala moja. Evo oni mi govore; Gdje je riječ Gospodnja? Neka dođe! Ali ja se nijesam smeo slijedeći tebe kao pastira: i dana čovječjega nijesam poželio, ti znaš. Sto je izišlo iz mojih ustiju, bilo je pravo pred očima tvojim. Ne budi mi na strah ti, koji si nada moja u dan nevolje. Neka se postide, koji me progone, a ja da se ne postidim; neka se straše oni, a' ja da se H ne strašim. Pusti na njih dan nevolje, i dvostrukim udarcem skrši ih. Gospodine Bože naš.","knRef":"Kniewald 1942, str. 208–209 (snimka 105) (OCR)"},"4e4649253094b630":{"t":"Ps 30, 20 i 22\nMiroljubivo su mi govorili neprijatelji moji, a mržnjom su mi svojom dodijavali. Vidi, Gospodine, nemoj šutjeti, nemoj se udaljiti od mene.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega.","kn":"(Ps. 34, 20, 22). Neprijatelji moji ne govore neprijateljski, već smišljahu prijevaru protiv mirnih na zemlji. Vidi, ^Gospodine, nemoj šutjeti, ne udaljuj se od mene!\n\n(Ps. 102, 10). Gospodine, ne postupaj s nama po grijesima našim i ne vraćaj nam po nepravdama našim. (Ps. 78, 8, 9) Gospodine, ne opominji se pređašnjih bezakonja naših, već neka nas brzo preteče milosrđe Tvoje, jer smo postali veoma ubogi (Ovdje se poklekne.) Pomozi nam. Bože, spasitelju naš, i radi slave imena svoga izbavi nas. Gospodine, i očisti nas od grijeha naših radi imena svoga.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"10fe1474078dc070":{"t":"Iv 11, 47-54\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme svećenički poglavari i farizeji sazovu vijeće protiv Isusa i pitali se: Što da učinimo? Ovaj čovjek čini mnoga čudesa. Ako ga tako pustimo, svi će vjerovati u njega, pa će doći Rimljani, osvojit će nam zemlju i narod. A jedan od njih koji se zvao Kaifa, a bio je te godine veliki svećenik, reče im: Vi ne znate ništa. Vi ne mislite da vam je bolje da jedan čovjek umre za narod, nego da svi propadnu. Ovo nije kazao sam od sebe, nego jer je bio te godine veliki svećenik, prorekao je da treba Isus umrijeti za narod, i ne samo za narod, nego da Božju djecu razasutu privede k jedinstvu. Toga su ga dana odlučili ubiti. Zato se Isus nije više javno pojavljivao među Židovima, nego se udalji otuda u osamljen kraj, u grad Efrem i ondje je boravio sa svojim učenicima.","kn":"t Slijedi sv. evanđelje po Ivanu (11, 47-54). U ono vrijeme sabraše glavari svećenički i farizeji skupštinu, te su govorili: Sto da činimo? Ovaj čovjek čini mnoga čudesa. Ako ga tako ostavimo, svi će vjerovati u njega, i doći će Rimljani, i otet će nam zemlju i narod. A jedan od njih, po imenu Kaifa, koji je bio one godine veliki svećenik, reče im; Vi ne znate ništa, i ne mislite, da je bolje za nas, da jedan čovjek umre za narod, negoli da sav narod propadne. A ovo ne reče sam od sebe, nego, jer je. bio veliki svećenik one godine, proreče, da Isusu valja umrijeti za narod, i ne samo za narod, nego da djecu Božju, koja su bila razasuta, sabere u jedno. Od toga dakle dana dogovoriše se, da ga ubiju. A Isus nije više hodao javno među Židovima, nego otide odanle, u kraj blizu pustinje, u grad, koji se zove EIrem, i ondje je boravio sa svojim učenicima.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"999bc3e9ef0b6773":{"t":"Ps 118, 12 i 121 i 42\nBlagoslovljen si, Gospodine! Uči me naredbama svojim i ne predaj me oholim klevetnicima mojim, pa ću moći odgovoriti onima koji me ruže.","kn":"(Ps. 118, 12, 121, 42). Blagoslovljen si. Gospodine, uči me pravdi svojoj i ne predaj me oholima, koji me kleveću, pa ću moći da odgovorim onima, koji mi se rugaju.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"1996770518d0c928":{"t":"Podaj nam, milosrdni Bože, da zavrijedimo uvijek dostojno služiti tvojim oltarima i spasiti se stalnim sudjelovanjem kod njih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, milosrdni Bože, da zaslužimo uvijek dostojno služiti Tvojim oltarima i biti spašeni neprestanim dioništvom Tvojih darova, po G. n.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu_ je dostojno i pravedno, pravo i. spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, po Kristu, 1 Gospodinu: našemu: jer Ti si ustanovio spase- I nje ljudskog roda na drvetu križa, da odanle us krsne život, odakle je proizašla smrt, te onaj, koji je na drvetu iznio pobjedu, na drvetu bude i svla- J dan po Kristu, Gospodinu našem, po kojem veličan stvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te i nebeske moći i blaženi Serafini zajedno slave, Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"f30fbe5fd17fb37f":{"t":"Ps 26, 12\nNe daj me, Gospodine, na volju onima koji me progone, jer ustadoše na mene lažni svjedoci, ali je bezakonje slagalo samo sebi.","kn":"(Ps. 26, 12). Nemoj me dati, Gospodine, na volju mučiteljima mojim, jer ustaju na me lažni svjedoci i bezakonje laže samo sebi.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"112f08ce6775225d":{"t":"<i>Pomolimo se</i>.\nNeprestana zaštita primljene žrtve neka nas, Gospodine, nikada ne ostavi i neka odstrani od nas sve što je štetno.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas. Gospodine, nikad ne ostavi zaštita žrtve, koju smo primili, i neka uvijek odagna od nas sve, što je štetno, p.o G. n.","knRef":"Kniewald 1942, str. 210–211 (snimka 106) (OCR)"},"132b441571d0c354":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nDaj, molimo, svemogući Bože, da ti mi koji molimo za milost tvoje zaštite, izbavljeni od svih zala, služimo bez straha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Dopusti, molimo', svemogući Bože, da oslobođeni sviju zala nesmetanim duhom Tebi služimo i težimo za milošću Tvoje zaštite, po G. n.","knRef":"Kniewald 1942, str. 160–161 (snimka 81) (OCR)"}}});
